 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    objects = []
    # Find solid 3x3 monochrome squares.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                objects.append((r + 1, c + 1, color))
    # Extend each square's middle row and column. Where differently colored
    # extensions cross, leave the crossing empty.
    lines = {}
    for r, c, color in objects:
        for x in range(w):
            lines[(r, x)] = lines.get((r, x), set()) | {color}
        for y in range(h):
            lines[(y, c)] = lines.get((y, c), set()) | {color}
    for (r, c), colors in lines.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
